const caseData = $json;

if (!caseData.runContext?.rawCaseId) {
  throw new Error(
    "pogs-rule-engine: incoming case has no rawCaseId"
  );
}

return {
  json: {
    caseData: caseData,

    configPaths: {
      semanticLayer:
        "/data/knowledge/clinical-automation-semantic-layer-v1.3.0.json",

      pogsReferences:
        "/data/knowledge/pogs-reference-values.json",

      pogsFormRules:
        "/data/knowledge/pogs-form-rules.json"
    }
  }
};

const binaryKeys =
  Object.keys($binary ?? {});

if (binaryKeys.length === 0) {
  throw new Error(
    "Semantic layer file returned no binary data"
  );
}

const binaryProperty =
  binaryKeys[0];

const buffer =
  await this.helpers.getBinaryDataBuffer(
    $itemIndex,
    binaryProperty
  );

let semanticLayer;

try {
  semanticLayer =
    JSON.parse(
      buffer.toString("utf8")
    );
} catch (error) {
  throw new Error(
    `Invalid semantic layer JSON: ${error.message}`
  );
}

/*
The Read File node may not preserve every
previous JSON field in every n8n configuration.

Retrieve the original preserved data from
the named earlier node.
*/
const prepared =
  $("Load Semantic Layer")
    .item
    .json;

return {
  json: {
    caseData:
      prepared.caseData,

    configPaths:
      prepared.configPaths,

    semanticLayer
  }
};

const binaryKeys =
  Object.keys($binary ?? {});

if (binaryKeys.length === 0) {
  throw new Error(
    "POGS reference file returned no binary data"
  );
}

const buffer =
  await this.helpers.getBinaryDataBuffer(
    $itemIndex,
    binaryKeys[0]
  );

let pogsReferences;

try {
  pogsReferences =
    JSON.parse(
      buffer.toString("utf8")
    );
} catch (error) {
  throw new Error(
    `Invalid POGS reference JSON: ${error.message}`
  );
}

const previous =
  $("Load POGS Reference Values")
    .item
    .json;

return {
  json: {
    caseData:
      previous.caseData,

    configPaths:
      previous.configPaths,

    semanticLayer:
      previous.semanticLayer,

    pogsReferences
  }
};

const binaryKeys =
  Object.keys($binary ?? {});

if (binaryKeys.length === 0) {
  throw new Error(
    "POGS form-rules file returned no binary data"
  );
}

const buffer =
  await this.helpers.getBinaryDataBuffer(
    $itemIndex,
    binaryKeys[0]
  );

let pogsFormRules;

try {
  pogsFormRules =
    JSON.parse(
      buffer.toString("utf8")
    );
} catch (error) {
  throw new Error(
    `Invalid POGS form-rules JSON: ${error.message}`
  );
}

const previous =
  $("Load POGS Form Rules")
    .item
    .json;

return {
  json: {
    caseData:
      previous.caseData,

    semanticLayer:
      previous.semanticLayer,

    pogsReferences:
      previous.pogsReferences,

    pogsFormRules: pogsFormRules,

    engineMeta: {
      formRulesMode:
        "REPORT_ONLY"
    }
  }
};

const caseData = $json.caseData;
const semanticLayer = $json.semanticLayer;
const pogsReferences = $json.pogsReferences;
const pogsFormRules = $json.pogsFormRules;
const engineMeta = $json.engineMeta;


function textOf(item) {

  if (
    typeof item === "string"
  ) {
    return item.trim();
  }

  return String(
    item?.term ??
    item?.sourceLabel ??
    ""
  ).trim();
}


function isNegated(item) {

  if (
    typeof item !== "object" ||
    item === null
  ) {
    return false;
  }

  return (
    item.negated === true
  );
}


const deterministicDiagnoses =
  caseData.diagnosisTerms ??
  caseData.extractedDiagnosisTerms ??
  [];


const aiDiagnoses =
  caseData.clinicalConcepts
    ?.aiDiagnosisTerms ??
  [];


const aiComorbidities =
  caseData.clinicalConcepts
    ?.aiComorbidityTerms ??
  [];


const aiProcedures =
  caseData.clinicalConcepts
    ?.aiProcedureTerms ??
  [];


const diagnosisConcepts = [];

for (
  const item of [
    ...deterministicDiagnoses,
    ...aiDiagnoses
  ]
) {

  const text =
    textOf(item);

  if (
    !text ||
    isNegated(item)
  ) {
    continue;
  }

  diagnosisConcepts.push({
    sourceText:
      text,

    normalizedText:
      text
        .toLowerCase()
        .replace(/\s+/g, " ")
        .trim(),

    source:
      aiDiagnoses.includes(item)
        ? "AI"
        : "DETERMINISTIC"
  });
}


const comorbidityConcepts =
  aiComorbidities
    .filter(
      item =>
        !isNegated(item)
    )
    .map(
      item => ({
        sourceText:
          textOf(item),

        normalizedText:
          textOf(item)
            .toLowerCase()
            .replace(/\s+/g, " ")
            .trim(),

        source:
          "AI"
      })
    );


const procedureConcepts =
  aiProcedures
    .map(
      item => ({
        sourceText:
          textOf(item),

        normalizedText:
          textOf(item)
            .toLowerCase()
            .replace(/\s+/g, " ")
            .trim(),

        source:
          "AI"
      })
    );


return {
  json: {
    caseData: caseData,

    semanticLayer: semanticLayer,
    pogsReferences: pogsReferences,
    pogsFormRules: pogsFormRules,

    engineMeta: engineMeta,

    clinicalConceptsNormalized: {
      diagnoses:
        diagnosisConcepts,

      comorbidities:
        comorbidityConcepts,

      procedures:
        procedureConcepts,

      pregnancyTypeText:
        caseData.clinicalConcepts
          ?.pregnancyTypeText ??
        null,

      deliveryMannerText:
        caseData.clinicalConcepts
          ?.deliveryMannerText ??
        null
    }
  }
};

const d = $json;

const concepts =
  d.clinicalConceptsNormalized;

const mapped = {
  gynecologicalDiagnosis: [],
  morbidities: {},
  gynemorbidities: {},
  medicalHistory: {},
  obstetricHistory: {},
  concomitantProcedure: {},
  obProcedure: {}
};

const unresolved = [];

const ignored = [];


function normalize(
  value
) {
  return String(
    value ?? ""
  )
    .toLowerCase()
    .replace(/\s+/g, " ")
    .trim();
}


/*
CONFIRMED POGS MAPPING

Prolapsed/submucous myoma:
category 12
condition 114
gyneStage 6
*/

for (
  const concept of
  concepts.diagnoses ?? []
) {

  const term =
    normalize(
      concept.normalizedText
    );


  const isSubmucousMyoma =
    (
      term.includes(
        "submucous myoma"
      ) ||
      term.includes(
        "submucosal myoma"
      )
    );


  if (
    isSubmucousMyoma
  ) {

    mapped
      .gynecologicalDiagnosis
      .push({
        categoryId:
          12,

        conditionId:
          114,

        gyneStage:
          6,

        others:
          null,

        othersField:
          null
      });

    continue;
  }


  /*
  Terms that we recognize clinically
  but do NOT yet have exact POGS
  diagnosis mapping for.
  */

  if (
    term ===
      "abnormal uterine bleeding" ||
    term.includes(
      "endometrial thickening"
    )
  ) {

    unresolved.push({
      type:
        "diagnosis",

      term:
        concept.sourceText,

      reason:
        "Clinical concept recognized but exact POGS mapping is not confirmed"
    });

    continue;
  }


  /*
  These are not gynecologicalDiagnosis
  entries by themselves.
  */

  if (
    term === "anemia" ||
    term.includes(
      "acute blood loss"
    ) ||
    term.includes(
      "obesity"
    )
  ) {

    ignored.push({
      type:
        "diagnosis",

      term:
        concept.sourceText,

      reason:
        "Not mapped as a POGS gynecologicalDiagnosis"
    });

    continue;
  }


  unresolved.push({
    type:
      "diagnosis",

    term:
      concept.sourceText,

    reason:
      "No deterministic POGS mapping exists"
  });
}


return {
  json: {
    ...d,

    pogsMapping: {
      mapped: mapped,
      unresolved: unresolved,
      ignored: ignored
    }
  }
};

const candidate =
  $json.candidate;

const artifact =
  $json.pogsFormRules;

const fields =
  artifact?.fields ?? {};


function valuePresent(
  value,
  constraints = {}
) {

  if (
    value === null ||
    value === undefined
  ) {
    return false;
  }

  if (
    typeof value === "string"
  ) {
    return (
      value.trim().length > 0
    );
  }

  if (
    Array.isArray(value)
  ) {

    const minimum =
      constraints.minItems ??
      constraints.minLength ??
      0;

    return (
      value.length >= minimum
    );
  }

  if (
    typeof value === "object"
  ) {

    const minimum =
      constraints.minItems ??
      constraints.minLength ??
      0;

    if (minimum > 0) {
      return (
        Object.keys(value)
          .length >= minimum
      );
    }

    return true;
  }

  // false and 0 are valid entered values.
  return true;
}


function evaluate(
  rule
) {

  if (!rule) {
    return true;
  }


  if (
    Array.isArray(rule.all)
  ) {

    return rule.all.every(
      evaluate
    );
  }


  if (
    Array.isArray(rule.any)
  ) {

    return rule.any.some(
      evaluate
    );
  }


  if (rule.eq) {

    const [
      field,
      expected
    ] =
      Object.entries(
        rule.eq
      )[0];

    return (
      candidate[field] ===
      expected
    );
  }


  if (rule.neq) {

    const [
      field,
      expected
    ] =
      Object.entries(
        rule.neq
      )[0];

    return (
      candidate[field] !==
      expected
    );
  }


  if (rule.in) {

    const [
      field,
      accepted
    ] =
      Object.entries(
        rule.in
      )[0];

    return (
      Array.isArray(accepted) &&
      accepted.includes(
        candidate[field]
      )
    );
  }


  if (rule.notIn) {

    const [
      field,
      rejected
    ] =
      Object.entries(
        rule.notIn
      )[0];

    return (
      Array.isArray(rejected) &&
      !rejected.includes(
        candidate[field]
      )
    );
  }


  if (rule.isNull) {

    return (
      candidate[
        rule.isNull
      ] == null
    );
  }


  if (rule.notNull) {

    return (
      candidate[
        rule.notNull
      ] != null
    );
  }


  if (rule.truthy) {

    return Boolean(
      candidate[
        rule.truthy
      ]
    );
  }


  if (rule.falsy) {

    return !Boolean(
      candidate[
        rule.falsy
      ]
    );
  }


  /*
  Unknown rule format.
  Do NOT silently return true.
  */

  return null;
}


const fieldStates = {};

const unknownRules = [];


for (
  const [
    fieldName,
    definition
  ] of Object.entries(
    fields
  )
) {

  let applicable =
    true;


  if (
    definition.applicableWhen
  ) {

    const result =
      evaluate(
        definition
          .applicableWhen
      );

    if (result === null) {

      applicable =
        null;

      unknownRules.push({
        field:
          fieldName,

        type:
          "applicableWhen",

        rule:
          definition
            .applicableWhen
      });

    } else {

      applicable =
        result;
    }
  }


  let required =
    definition
      .closeCaseRequired ===
    true;


  if (
    definition.requiredWhen
  ) {

    const result =
      evaluate(
        definition
          .requiredWhen
      );

    if (result === null) {

      required =
        null;

      unknownRules.push({
        field:
          fieldName,

        type:
          "requiredWhen",

        rule:
          definition
            .requiredWhen
      });

    } else {

      required =
        result;
    }
  }


  const value =
    candidate[
      fieldName
    ];


  const satisfied =
    required === true
      ? valuePresent(
          value,
          definition
        )
      : true;


  fieldStates[
    fieldName
  ] = {

    applicable,

    required,

    satisfied,

    value:
      value ?? null,

    controlType:
      definition
        .controlType ??
      null
  };
}


const missingRequiredFields =
  Object.entries(
    fieldStates
  )
    .filter(
      ([, state]) =>
        state.applicable === true &&
        state.required === true &&
        state.satisfied !== true
    )
    .map(
      ([field]) =>
        field
    );


return {
  json: {
    ...$json,

    candidate: {
      ...candidate,

      formEvaluation: {
        mode:
          $json.engineMeta
            ?.formRulesMode ??
          "ENFORCED",

        fieldStates: fieldStates,

        missingRequiredFields: missingRequiredFields,

        unknownRules: unknownRules
      }
    }
  }
};

const c =
  $json.candidate;

const issues = [];
const warnings = [];


/*
Core identity requirements
*/

if (!c.caseNum) {
  issues.push(
    "Missing caseNum"
  );
}

if (!c.birthDate) {
  issues.push(
    "Missing birthDate"
  );
}

if (!c.admissionDate) {
  issues.push(
    "Missing admissionDate"
  );
}


/*
Case classification
*/

if (
  c.isPregnancy === null ||
  c.isPregnancy === undefined
) {
  issues.push(
    "isPregnancy not classified"
  );
}

if (
  c.isGyne === null ||
  c.isGyne === undefined
) {
  issues.push(
    "isGyne not classified"
  );
}


/*
Delivery-state safety
*/

if (
  c.isPregnancy === true &&
  (
    c.isDelivered === null ||
    c.isDelivered === undefined
  )
) {

  issues.push(
    "Current pregnancy delivery status not established"
  );
}


/*
Gyne mapping
*/

if (
  c.isGyne === true &&
  (
    !Array.isArray(
      c.gynecologicalDiagnosis
    ) ||
    c.gynecologicalDiagnosis
      .length === 0
  )
) {

  issues.push(
    "Gyne case has no confirmed POGS gynecologicalDiagnosis mapping"
  );
}


/*
Unresolved mappings
*/

for (
  const unresolved of
  $json.pogsMapping
    ?.unresolved ?? []
) {

  warnings.push(
    `Unresolved clinical mapping: ${
      unresolved.term ??
      "unknown"
    }`
  );
}


/*
Form evaluation

When formRulesMode is REPORT_ONLY,
missing required POGS fields and
unknown rules become warnings.
*/

const form =
  c.formEvaluation ?? {};

for (
  const field of
  form.missingRequiredFields ??
  []
) {

  const message =
    "POGS form rule requires: " +
    field;

  if (
    (form.mode ?? "REPORT_ONLY") ===
    "ENFORCED"
  ) {
    issues.push(message);
  } else {
    warnings.push(message);
  }
}


for (
  const rule of
  form.unknownRules ??
  []
) {

  const message =
    "POGS form rule could not be evaluated: " +
    rule.field;

  if (
    (form.mode ?? "REPORT_ONLY") ===
    "ENFORCED"
  ) {
    issues.push(message);
  } else {
    warnings.push(message);
  }
}


/*
Reference sanity for confirmed
gynecologicalDiagnosis structures.
*/

for (
  const diagnosis of
  c.gynecologicalDiagnosis ??
  []
) {

  if (
    !Number.isInteger(
      diagnosis.categoryId
    ) ||
    !Number.isInteger(
      diagnosis.conditionId
    )
  ) {

    issues.push(
      "Invalid gynecologicalDiagnosis reference structure"
    );
  }
}


/*
Final state
*/

const readyForPOGS =
  issues.length === 0;


return {
  json: {
    ...c,

    unresolvedMappings:
      $json.pogsMapping
        ?.unresolved ??
      [],

    ignoredMappings:
      $json.pogsMapping
        ?.ignored ??
      [],

    validation: {

      readyForPOGS: readyForPOGS,

      needsReview:
        !readyForPOGS,

      issues: issues,

      warnings: warnings,

      formRulesMode:
        form.mode ??
        "REPORT_ONLY"
    }
  }
};
